-- v2 hierarchy seed for "entrepreneurship". GENERATED by `npm run v2:hierarchy` in coursegen; do not edit by hand.
--
-- Creates 11 adventure(s), 11 saga(s), 44 topic(s), 44 lesson(s) and 104 topic-to-KC link(s).
-- Create-only and idempotent: every INSERT is ON CONFLICT DO NOTHING, so a rerun changes nothing and an existing row is never overwritten.
-- Ids are UUIDv5 of the slug path (ids.json maps each lesson slug to its public.lessons.id).
-- Nothing is published: adventures, sagas and topics are inserted as draft and lessons as review. A human publishes.
-- The course row is only created when the slug is absent. Adventures resolve the course by slug and append after its existing adventures.
-- Knowledge components resolve by key from public.kc (seed:kc must have loaded them, draft ones included).
--
-- REVIEW GATE: the file ends in ROLLBACK, so running it as-is persists nothing. It still executes every statement and the
-- completeness check, which raises if any row or link did not land. After reading it, replace the final ROLLBACK with COMMIT.

BEGIN;

DO $lfkc$
DECLARE v_missing text;
BEGIN
  SELECT string_agg(k.key, ', ') INTO v_missing FROM unnest(ARRAY['biz.agreements', 'biz.break-even', 'biz.budget-decisions', 'biz.build-within-constraints', 'biz.business-ethics', 'biz.business-model', 'biz.communicate-value', 'biz.conflict-resolution', 'biz.consultative-selling', 'biz.cost-vs-price', 'biz.customer-feedback', 'biz.customer-interviews', 'biz.deal-red-flags', 'biz.delegation', 'biz.ethical-persuasion', 'biz.evidence-from-customers', 'biz.full-costing', 'biz.leading-growth', 'biz.long-term-vision', 'biz.make-and-test', 'biz.margin', 'biz.market-signals', 'biz.mvp', 'biz.negotiation', 'biz.opportunity-evaluation', 'biz.pricing-strategy', 'biz.profit', 'biz.real-problems', 'biz.reputation', 'biz.revenue', 'biz.risk-and-reward', 'biz.sales-funnel', 'biz.solution-ideas', 'biz.team-culture', 'biz.what-is-price', 'life.advertising-literacy', 'life.scam-awareness', 'money.add-money', 'money.percent-intro', 'money.simple-budget', 'money.unit-price']) AS k(key)
  WHERE NOT EXISTS (SELECT 1 FROM public.kc WHERE kc.key = k.key);
  IF v_missing IS NOT NULL THEN RAISE EXCEPTION 'knowledge components missing from public.kc (run backend seed:kc first): %', v_missing; END IF;
END
$lfkc$;

