  ('cc37b9c6-7701-56e9-a472-2ac32e353a8a', 'f2845c61-e785-50d0-89e0-49236f040ed4', 4, 'ent-1012-08-first-customers-speak', $lf${"en-US":"First customers speak","es-MX":"Los primeros clientes hablan","pt-BR":"Os primeiros clientes falam"}$lf$::jsonb, $lf${"en-US":"Listen to what customers say without defending, decide which comments should change the product, and check the change.","es-MX":"Escuchar lo que dicen los clientes sin defenderse, decidir qué comentarios deben cambiar el producto y comprobar el cambio.","pt-BR":"Ouvir o que os clientes dizem sem se defender, decidir quais comentários devem mudar o produto e verificar a mudança."}$lf$::jsonb, 'teaching', 'draft'),
  ('6e0c9e26-d410-57d9-a6c8-0fde5df973ac', '1bfe4b9f-d708-5312-aebd-f71a0e46142f', 1, 'ent-1012-09-the-twenty-second-pitch', $lf${"en-US":"The twenty-second pitch","es-MX":"El pitch de veinte segundos","pt-BR":"O pitch de vinte segundos"}$lf$::jsonb, $lf${"en-US":"Explain clearly what a product does, who it is for and which problem it solves.","es-MX":"Explicar con claridad qué hace un producto, para quién es y qué problema resuelve.","pt-BR":"Explicar com clareza o que um produto faz, para quem é e que problema resolve."}$lf$::jsonb, 'teaching', 'draft'),
  ('05661cf9-6fc8-50cb-a8eb-7bbfa78c1896', '1bfe4b9f-d708-5312-aebd-f71a0e46142f', 2, 'ent-1012-10-cost-and-price-per-bag', $lf${"en-US":"Cost and price per bag","es-MX":"Costo y precio por bolsa","pt-BR":"Custo e preço por sacola"}$lf$::jsonb, $lf${"en-US":"Tell apart what it costs to make something from the price it sells for.","es-MX":"Distinguir lo que cuesta hacer algo del precio al que se vende.","pt-BR":"Distinguir o que custa fazer algo do preço pelo qual é vendido."}$lf$::jsonb, 'teaching', 'draft'),
  ('e91a1275-fa68-508f-ad02-d1b6c4b0e942', '1bfe4b9f-d708-5312-aebd-f71a0e46142f', 3, 'ent-1012-11-choose-the-price', $lf${"en-US":"Choose the price","es-MX":"Elige el precio","pt-BR":"Escolha o preço"}$lf$::jsonb, $lf${"en-US":"Choose a price that covers costs, leaves a profit and buyers still accept.","es-MX":"Elegir un precio que cubra los costos, deje ganancia y los compradores acepten.","pt-BR":"Escolher um preço que cubra os custos, deixe lucro e os compradores aceitem."}$lf$::jsonb, 'teaching', 'draft'),
  ('957b3f69-dbfd-540e-b6cb-9ce571258d18', '1bfe4b9f-d708-5312-aebd-f71a0e46142f', 4, 'ent-1012-12-spend-what-you-have', $lf${"en-US":"Spend what you have","es-MX":"Gasta lo que tienes","pt-BR":"Gaste o que você tem"}$lf$::jsonb, $lf${"en-US":"Choose what a small business spends on when it cannot pay for everything.","es-MX":"Elegir en qué gasta un pequeño negocio cuando no alcanza para todo.","pt-BR":"Escolher em que um pequeno negócio gasta quando não dá para pagar tudo."}$lf$::jsonb, 'teaching', 'draft'),
  ('327855b9-07f0-5e40-9c53-1a90cce5d1b2', 'f3ba3e87-4b84-5e82-8bae-4d5301ab59e0', 1, 'ent-1317-01-ask-before-you-build', $lf${"en-US":"Ask before you build","es-MX":"Pregunta antes de construir","pt-BR":"Pergunte antes de construir"}$lf$::jsonb, $lf${"en-US":"Plan and run an interview with open, non-leading questions that lets the person describe the problem in their own words.","es-MX":"Planear y hacer una entrevista con preguntas abiertas que no dirigen, para que la persona describa el problema con sus palabras.","pt-BR":"Planejar e fazer uma entrevista com perguntas abertas que não induzem, para a pessoa descrever o problema com suas palavras."}$lf$::jsonb, 'teaching', 'draft'),
  ('250e0890-c017-57ef-a139-4dfa71661f32', 'f3ba3e87-4b84-5e82-8bae-4d5301ab59e0', 2, 'ent-1317-02-one-comment-is-a-clue', $lf${"en-US":"One comment is a clue","es-MX":"Un comentario es una pista","pt-BR":"Um comentário é uma pista"}$lf$::jsonb, $lf${"en-US":"Compare several interviews, separate facts from opinions, and treat one comment as a clue rather than a pattern.","es-MX":"Comparar varias entrevistas, separar hechos de opiniones y tratar un comentario aislado como una pista, no como un patrón.","pt-BR":"Comparar várias entrevistas, separar fatos de opiniões e tratar um comentário isolado como pista, não como padrão."}$lf$::jsonb, 'teaching', 'draft'),
  ('4b8f60d6-d652-52ac-b3ee-c9171a6c54d8', 'f3ba3e87-4b84-5e82-8bae-4d5301ab59e0', 3, 'ent-1317-03-sell-by-asking', $lf${"en-US":"Sell by asking","es-MX":"Vende preguntando","pt-BR":"Venda perguntando"}$lf$::jsonb, $lf${"en-US":"Sell by first asking about the customer's problem, connecting only the relevant part of the product, and closing with a question.","es-MX":"Vender preguntando primero por el problema del cliente, conectando solo la parte útil del producto y cerrando con una pregunta.","pt-BR":"Vender perguntando primeiro sobre o problema do cliente, ligando só a parte útil do produto e fechando com uma pergunta."}$lf$::jsonb, 'teaching', 'draft'),
  ('180b41ea-77b0-5a8b-ae3e-fa9d7164ade2', 'f3ba3e87-4b84-5e82-8bae-4d5301ab59e0', 4, 'ent-1317-04-where-the-funnel-leaks', $lf${"en-US":"Where the funnel leaks","es-MX":"Dónde se fuga el embudo","pt-BR":"Onde o funil vaza"}$lf$::jsonb, $lf${"en-US":"Count people at each stage of a sales funnel, find the conversion rate, and pick the stage that loses the most people.","es-MX":"Contar a las personas en cada etapa del embudo de ventas, calcular la tasa de conversión y elegir la etapa que más gente pierde.","pt-BR":"Contar as pessoas em cada etapa do funil de vendas, calcular a taxa de conversão e escolher a etapa que mais perde gente."}$lf$::jsonb, 'teaching', 'draft'),
  ('43e9df25-2a3c-5d45-a1ac-ea0876643cc7', '1ac9b8e2-aadd-5407-b732-c3b07182b1b9', 1, 'ent-1317-05-the-real-cost-of-one', $lf${"en-US":"The real cost of one","es-MX":"El costo real de uno","pt-BR":"O custo real de um"}$lf$::jsonb, $lf${"en-US":"Add fixed, variable and hidden costs and the value of your time to find the real cost of each unit.","es-MX":"Sumar costos fijos, variables y escondidos y el valor de tu tiempo para encontrar el costo real de cada unidad.","pt-BR":"Somar custos fixos, variáveis e escondidos e o valor do seu tempo para encontrar o custo real de cada unidade."}$lf$::jsonb, 'teaching', 'draft'),
  ('bb0436c5-1750-55ce-8813-9d7ae13bd42c', '1ac9b8e2-aadd-5407-b732-c3b07182b1b9', 2, 'ent-1317-06-how-much-is-kept', $lf${"en-US":"How much is kept","es-MX":"Cuánto te queda","pt-BR":"Quanto fica com você"}$lf$::jsonb, $lf${"en-US":"Find the margin in currency and as a percentage of the price, and show how a discount reduces it.","es-MX":"Calcular el margen en dinero y como porcentaje del precio, y mostrar cómo un descuento lo reduce.","pt-BR":"Calcular a margem em dinheiro e como porcentagem do preço, e mostrar como um desconto a reduz."}$lf$::jsonb, 'teaching', 'draft'),
  ('9e584a38-7fde-54c0-b104-5c2c4c6389a8', '1ac9b8e2-aadd-5407-b732-c3b07182b1b9', 3, 'ent-1317-07-the-break-even-point', $lf${"en-US":"The break-even point","es-MX":"El punto de equilibrio","pt-BR":"O ponto de equilíbrio"}$lf$::jsonb, $lf${"en-US":"Find how many units must be sold to cover fixed costs, and how price and fixed costs move that point.","es-MX":"Calcular cuántas unidades hay que vender para cubrir los costos fijos y cómo el precio y los costos fijos mueven ese punto.","pt-BR":"Calcular quantas unidades precisam ser vendidas para cobrir os custos fixos e como o preço e os custos fixos movem esse ponto."}$lf$::jsonb, 'teaching', 'draft'),
