  ('94b06556-1e7e-540a-ba47-3d3a90ce7a88', '78beaf2a-1118-5608-9a08-2adcefd4808b', 1, 'ent-1317-09-a-deal-both-accept', $lf${"en-US":"A deal both sides accept","es-MX":"Un trato que ambos aceptan","pt-BR":"Um acordo que os dois aceitam"}$lf$::jsonb, $lf${"en-US":"Set your limit before negotiating, find what the other person really wants, trade low-cost concessions, and say no respectfully.","es-MX":"Fijar tu límite antes de negociar, descubrir qué quiere de verdad la otra persona, ceder lo que te cuesta poco y decir que no con respeto.","pt-BR":"Definir seu limite antes de negociar, descobrir o que a outra pessoa realmente quer, ceder o que custa pouco e dizer não com respeito."}$lf$::jsonb, 'teaching', 'draft'),
  ('37c25c1c-f235-5e44-8923-c5b7a478f55f', '78beaf2a-1118-5608-9a08-2adcefd4808b', 2, 'ent-1317-10-persuade-without-tricks', $lf${"en-US":"Persuade without tricks","es-MX":"Convence sin trucos","pt-BR":"Convença sem truques"}$lf$::jsonb, $lf${"en-US":"Tell persuasion with real reasons from manipulation with lies, fake urgency or invented reviews, and choose the honest way.","es-MX":"Distinguir la persuasión con razones reales de la manipulación con mentiras, urgencia falsa o reseñas inventadas, y elegir el camino honesto.","pt-BR":"Distinguir a persuasão com razões reais da manipulação com mentiras, urgência falsa ou avaliações inventadas, e escolher o caminho honesto."}$lf$::jsonb, 'teaching', 'draft'),
