  ('bee1bf2b-b0fc-5677-af53-6de783a36c8a', '78beaf2a-1118-5608-9a08-2adcefd4808b', 4, 'ent-1317-12-the-way-we-work', $lf${"en-US":"The way we work","es-MX":"Nuestra forma de trabajar","pt-BR":"Nosso jeito de trabalhar"}$lf$::jsonb, $lf${"en-US":"Explain how habits, specific recognition, the way mistakes are handled and a leader's example shape a team's culture.","es-MX":"Explicar cómo los hábitos, el reconocimiento específico, la forma de tratar los errores y el ejemplo del líder forman la cultura de un equipo.","pt-BR":"Explicar como hábitos, reconhecimento específico, a forma de lidar com erros e o exemplo do líder formam a cultura de uma equipe."}$lf$::jsonb, 'teaching', 'draft'),
  ('9a4d625a-af93-56ce-bb28-a3659e76b548', '15b7536b-e795-5367-b2f2-2326705ec6d4', 1, 'ent-adult-01-is-it-a-real-opportunity', $lf${"en-US":"Is it a real opportunity?","es-MX":"¿Es una oportunidad real?","pt-BR":"É uma oportunidade real?"}$lf$::jsonb, $lf${"en-US":"Decide whether an idea is a real opportunity by weighing market size, competition, your own advantage and its risks.","es-MX":"Decidir si una idea es una oportunidad real sopesando el tamaño del mercado, la competencia, tu ventaja propia y sus riesgos.","pt-BR":"Decidir se uma ideia é uma oportunidade real pesando o tamanho do mercado, a concorrência, sua própria vantagem e os riscos."}$lf$::jsonb, 'teaching', 'draft'),
  ('25ee39fa-e394-51ee-a9d7-d1c683cddd0b', '15b7536b-e795-5367-b2f2-2326705ec6d4', 2, 'ent-adult-02-how-many-jobs-to-break-even', $lf${"en-US":"How many repairs to break even?","es-MX":"¿Cuántas reparaciones hasta el punto de equilibrio?","pt-BR":"Quantos consertos até o ponto de equilíbrio?"}$lf$::jsonb, $lf${"en-US":"Find how many units must be sold to cover fixed costs, and how price and fixed costs move that point.","es-MX":"Calcular cuántas unidades hay que vender para cubrir los costos fijos y cómo el precio y los costos fijos mueven ese punto.","pt-BR":"Calcular quantas unidades precisam ser vendidas para cobrir os custos fixos e como o preço e os custos fixos movem esse ponto."}$lf$::jsonb, 'teaching', 'draft'),
  ('c3c482b8-af32-5867-a68c-da74618cbc3c', '15b7536b-e795-5367-b2f2-2326705ec6d4', 3, 'ent-adult-03-the-price-you-can-defend', $lf${"en-US":"The price you can defend","es-MX":"El precio que puedes defender","pt-BR":"O preço que você consegue defender"}$lf$::jsonb, $lf${"en-US":"Choose a price that covers costs, leaves a profit and buyers still accept.","es-MX":"Elegir un precio que cubra los costos, deje ganancia y los compradores acepten.","pt-BR":"Escolher um preço que cubra os custos, deixe lucro e os compradores aceitem."}$lf$::jsonb, 'teaching', 'draft'),
  ('c7beeccc-76c4-51d0-bbd7-a4eb68240bb1', '15b7536b-e795-5367-b2f2-2326705ec6d4', 4, 'ent-adult-04-the-whole-model-on-one-page', $lf${"en-US":"The whole model on one page","es-MX":"El modelo completo en una página","pt-BR":"O modelo completo em uma página"}$lf$::jsonb, $lf${"en-US":"Connect problem, customer, product, price, channel and team into one coherent business model.","es-MX":"Conectar problema, cliente, producto, precio, canal y equipo en un solo modelo de negocio coherente.","pt-BR":"Conectar problema, cliente, produto, preço, canal e equipe em um único modelo de negócio coerente."}$lf$::jsonb, 'teaching', 'draft'),
  ('3adaf1d3-dc0e-5b2e-9cf0-d8324a219d31', '679e9f5c-0509-5114-9b1b-bf6510dd0786', 1, 'ent-adult-05-warning-signs-in-a-deal', $lf${"en-US":"Spot warning signs in a deal","es-MX":"Detecta las señales de alerta de un trato","pt-BR":"Identifique os sinais de alerta de um negócio"}$lf$::jsonb, $lf${"en-US":"Spot the warning signs of a risky deal: an offer too good to be true, nothing in writing, full payment up front, changing terms or pressure.","es-MX":"Notar las señales de un trato riesgoso: una oferta demasiado buena, nada por escrito, pago total por adelantado, términos que cambian o presión.","pt-BR":"Notar os sinais de um negócio arriscado: oferta boa demais, nada por escrito, pagamento total adiantado, termos que mudam ou pressão."}$lf$::jsonb, 'teaching', 'draft'),
  ('df227fb1-255e-5040-8762-cc8b97d79a74', '679e9f5c-0509-5114-9b1b-bf6510dd0786', 2, 'ent-adult-06-an-agreement-that-says-it', $lf${"en-US":"Check an agreement before signing","es-MX":"Revisa un acuerdo antes de firmarlo","pt-BR":"Confira um acordo antes de assinar"}$lf$::jsonb, $lf${"en-US":"Check that an agreement says what is delivered, when, for how much and what happens if someone does not comply; read it all and ask before signing.","es-MX":"Revisar que un acuerdo diga qué se entrega, cuándo, por cuánto y qué pasa si alguien no cumple; leerlo completo y preguntar antes de firmar.","pt-BR":"Verificar se um acordo diz o que é entregue, quando, por quanto e o que acontece se alguém não cumprir; ler tudo e perguntar antes de assinar."}$lf$::jsonb, 'teaching', 'draft'),
  ('34221c48-a2c2-502e-82be-04f93f71088e', '679e9f5c-0509-5114-9b1b-bf6510dd0786', 3, 'ent-adult-07-negotiate-with-a-limit', $lf${"en-US":"Negotiate with a limit","es-MX":"Negocia con un límite","pt-BR":"Negocie com um limite"}$lf$::jsonb, $lf${"en-US":"Set your limit before negotiating, find what the other person really wants, trade low-cost concessions, and say no respectfully.","es-MX":"Fijar tu límite antes de negociar, descubrir qué quiere de verdad la otra persona, ceder lo que te cuesta poco y decir que no con respeto.","pt-BR":"Definir seu limite antes de negociar, descobrir o que a outra pessoa realmente quer, ceder o que custa pouco e dizer não com respeito."}$lf$::jsonb, 'teaching', 'draft'),
  ('2cacd1cd-11a9-520e-92ea-13da5176c400', '679e9f5c-0509-5114-9b1b-bf6510dd0786', 4, 'ent-adult-08-trust-after-a-bad-review', $lf${"en-US":"Trust after a bad review","es-MX":"Confianza tras una mala reseña","pt-BR":"Confiança após uma avaliação ruim"}$lf$::jsonb, $lf${"en-US":"Explain that reputation is the trust others give you after past dealings, and respond to criticism in a way that protects it.","es-MX":"Explicar que la reputación es la confianza que otros te dan por tratos anteriores y responder a una crítica de forma que la proteja.","pt-BR":"Explicar que a reputação é a confiança que os outros dão a você por negócios anteriores e responder a críticas de um jeito que a proteja."}$lf$::jsonb, 'teaching', 'draft'),
  ('9d697bf7-76f0-5c08-8a12-87825aa7b48b', '6f28c928-54dc-5ea6-89e1-7ff5366322ad', 1, 'ent-adult-09-two-sides-of-a-conflict', $lf${"en-US":"Two sides of a conflict","es-MX":"Dos lados de un conflicto","pt-BR":"Dois lados de um conflito"}$lf$::jsonb, $lf${"en-US":"Hear both sides, address the problem rather than the person, find the interest behind the conflict, decide, and repair the relationship.","es-MX":"Escuchar a ambas partes, hablar del problema y no de la persona, encontrar el interés detrás del conflicto, decidir y reparar la relación.","pt-BR":"Ouvir os dois lados, tratar do problema e não da pessoa, encontrar o interesse por trás do conflito, decidir e reparar a relação."}$lf$::jsonb, 'teaching', 'draft'),
  ('351dec79-6de8-5c16-b0a2-ce07e604586a', '6f28c928-54dc-5ea6-89e1-7ff5366322ad', 2, 'ent-adult-10-growing-from-two-to-five', $lf${"en-US":"Growing from two to five","es-MX":"De dos a cinco personas","pt-BR":"De duas a cinco pessoas"}$lf$::jsonb, $lf${"en-US":"Adapt how a growing team works: define clear roles, welcome new people well, and respond respectfully when a role does not fit.","es-MX":"Adaptar cómo trabaja un equipo que crece: definir roles claros, recibir bien a quien llega y responder con respeto cuando un rol no encaja.","pt-BR":"Adaptar como uma equipe que cresce trabalha: definir papéis claros, receber bem quem chega e responder com respeito quando um papel não combina."}$lf$::jsonb, 'teaching', 'draft'),
  ('af971f83-da23-5437-aa89-cb97047acc90', '6f28c928-54dc-5ea6-89e1-7ff5366322ad', 3, 'ent-adult-11-three-requests-one-answer', $lf${"en-US":"Three requests, one answer","es-MX":"Tres solicitudes, una respuesta","pt-BR":"Três pedidos, uma resposta"}$lf$::jsonb, $lf${"en-US":"Treat customers fairly, make honest claims, protect customer data, notice conflicts of interest, and say no to requests that are not right.","es-MX":"Tratar con justicia a los clientes, prometer con honestidad, proteger sus datos, notar conflictos de interés y decir que no a lo que no está bien.","pt-BR":"Tratar os clientes com justiça, prometer com honestidade, proteger os dados deles, notar conflitos de interesse e dizer não ao que não está certo."}$lf$::jsonb, 'teaching', 'draft'),
  ('bd225549-4808-5148-a2b9-18fb3a4efa3b', '6f28c928-54dc-5ea6-89e1-7ff5366322ad', 4, 'ent-adult-12-the-year-ahead', $lf${"en-US":"The year ahead","es-MX":"El año por delante","pt-BR":"O ano pela frente"}$lf$::jsonb, $lf${"en-US":"Set a concrete one-year goal, decide what to stop doing, prepare a contingency plan and measure success beyond money.","es-MX":"Fijar una meta concreta a un año, decidir qué dejar de hacer, preparar un plan de contingencia y medir el éxito más allá del dinero.","pt-BR":"Definir uma meta concreta para um ano, decidir o que parar de fazer, preparar um plano de contingência e medir o sucesso além do dinheiro."}$lf$::jsonb, 'teaching', 'draft')
ON CONFLICT DO NOTHING;

